SELECT ?subject ?maker WHERE {
  ?subject ?labelProp "Monument voor Amsterdam" .
  OPTIONAL { ?subject ?makerProp ?maker .
             FILTER(CONTAINS(LCASE(STR(?makerProp)), "maker")) }
}

SELECT ?subject ?pred ?maker WHERE {
  ?subject ?pred ?title .
  FILTER(CONTAINS(LCASE(STR(?title)), "monument voor amsterdam"))
  OPTIONAL { ?subject ?makerProp ?maker .
             FILTER(CONTAINS(LCASE(STR(?makerProp)), "maker")) }
}
LIMIT 20

SELECT ?subject ?maker WHERE {
  ?subject ?p "Monument voor Amsterdam"@nl .
  ?subject ?makerProp ?maker .
  FILTER(CONTAINS(LCASE(STR(?makerProp)), "maker"))
}
LIMIT 10

SELECT ?subject ?maker WHERE {
  ?subject ?labelProp ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "markt op het waterlooplein"))
  OPTIONAL { ?subject <https://schema.org/creator> ?maker }
  OPTIONAL { ?subject <http://schema.org/creator> ?maker }
}
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?subject ?label WHERE {
  ?subject rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "troelstra"))
}
LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label WHERE {
  ?s ?p ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "fire") && CONTAINS(LCASE(STR(?label)), "town hall"))
}
LIMIT 10

