PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(CONTAINS(STR(?o), "A 10053") || CONTAINS(STR(?s), "A 10053"))
}
LIMIT 20

SELECT ?s ?label WHERE {
  ?s ?p ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "old town hall") && CONTAINS(LCASE(STR(?label)), "1652"))
}
LIMIT 10

PREFIX am: <http://purl.org/collections/nl/am/>
SELECT ?type ?value ?unit WHERE {
  <http://purl.org/collections/nl/am/proxy-11> am:dimension ?dim .
  ?dim am:dimensionType ?type ;
       am:dimensionValue ?value .
  OPTIONAL { ?dim am:dimensionUnit ?unit }
}

PREFIX am: <http://purl.org/collections/nl/am/>
SELECT ?type ?value ?unit WHERE {
  <http://purl.org/collections/nl/am/proxy-12> am:dimension ?dim .
  ?dim am:dimensionType ?type ;
       am:dimensionValue ?value .
  OPTIONAL { ?dim am:dimensionUnit ?unit }
}

SELECT ?subject ?predicate ?object WHERE {
  ?subject ?predicate ?object .
  FILTER(CONTAINS(LCASE(STR(?subject)), "luna") || CONTAINS(LCASE(STR(?object)), "luna city"))
}
LIMIT 20

SELECT ?subject ?isbn WHERE {
  ?subject ?p ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "atlas of forgotten stars"))
  OPTIONAL { ?subject <http://schema.org/isbn> ?isbn }
  OPTIONAL { ?subject <http://purl.org/ontology/bibo/isbn> ?isbn }
}
LIMIT 10
